-- Additive migration. Apply consciously after backup; never reset production.
create extension if not exists pgcrypto;
create table public.mechanics (id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1);
insert into public.mechanics(name) values ('César'), ('Maranhão');
create table public.authorized_devices(id uuid primary key default gen_random_uuid(), token_hash text not null unique, label text not null, created_at timestamptz not null default now(), expires_at timestamptz not null, revoked_at timestamptz);
create table public.access_sessions(id uuid primary key default gen_random_uuid(),device_id uuid not null references public.authorized_devices,token_hash text not null unique,created_at timestamptz not null default now(),expires_at timestamptz not null,revoked_at timestamptz);
create table public.access_attempts(key text primary key, attempts int not null, window_start timestamptz not null);
create table public.device_challenges(id uuid primary key default gen_random_uuid(), token_hash text not null, browser_hash text not null,expires_at timestamptz not null,used_at timestamptz);
create table public.bootstrap_uses(token_hash text primary key,used_at timestamptz not null default now());
create table public.confirmations(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.access_sessions,mechanic_id uuid not null references public.mechanics,operation_hash text not null,expires_at timestamptz not null,used_at timestamptz);
create table public.operation_results(id uuid primary key, session_id uuid not null references public.access_sessions,operation_hash text not null,result jsonb not null,created_at timestamptz not null default now());
create table public.audit_events(id uuid primary key default gen_random_uuid(),entity text not null,entity_id uuid,action text not null,before_data jsonb,after_data jsonb,mechanic_id uuid references public.mechanics,operation_id uuid,reason text,created_at timestamptz not null default now());
create index audit_entity on public.audit_events(entity,entity_id,created_at desc);
create table public.app_settings(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null unique, value text not null);
create table public.locations(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, code text not null unique, parent_id uuid references public.locations, kind text not null default 'shelf', active boolean not null default true, check(parent_id is distinct from id));
create table public.organizations(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, kind text not null check(kind in ('supplier','owner','third_party')), email text, phone text);
create table public.aircraft(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, registration text not null unique, manufacturer text, model text, serial_number text, location_id uuid references public.locations, status text not null default 'active' check(status in ('active','inactive')));
create table public.part_catalog(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, part_number text not null, manufacturer text, category text, unit text not null default 'un', minimum_stock numeric not null default 0 check(minimum_stock>=0), unique(part_number,manufacturer));
create table public.part_instances(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, catalog_id uuid not null references public.part_catalog, serial_number text not null, owner_id uuid references public.organizations, location_id uuid references public.locations, aircraft_id uuid references public.aircraft, position text, condition text not null default 'pending' check(condition in ('pending','serviceable','unserviceable','quarantine','scrap')), documentation text not null default 'pending' check(documentation in ('pending','complete')), logistics text not null default 'stored' check(logistics in ('stored','installed','external','transit','unknown')), unique(catalog_id,serial_number), check((logistics='installed' and aircraft_id is not null and location_id is null) or (logistics<>'installed' and aircraft_id is null)), check(logistics<>'unknown' or location_id is null));
create table public.stock_lots(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, catalog_id uuid not null references public.part_catalog, code text not null, location_id uuid not null references public.locations, owner_id uuid references public.organizations, supplier_id uuid references public.organizations, quantity numeric not null default 0 check(quantity>=0), reserved numeric not null default 0 check(reserved>=0 and reserved<=quantity), expires_at date, opened_at date, condition text not null default 'pending' check(condition in ('pending','serviceable','unserviceable','quarantine','scrap')), documentation text not null default 'pending' check(documentation in ('pending','complete')), unit_cost numeric check(unit_cost>=0), unique(catalog_id,code,location_id));
create table public.stock_reservations(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, lot_id uuid not null references public.stock_lots, quantity numeric not null check(quantity>0), status text not null default 'active' check(status in ('active','released','consumed')), purpose text not null);
create table public.stock_movements(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, lot_id uuid not null references public.stock_lots, kind text not null, quantity numeric not null, destination_id uuid references public.locations, reason text not null, operation_id uuid not null, reservation_id uuid references public.stock_reservations);
create table public.physical_counts(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, location_id uuid not null references public.locations, status text not null default 'open' check(status in ('open','closed')));
create table public.physical_count_items(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, count_id uuid not null references public.physical_counts, lot_id uuid not null references public.stock_lots, expected numeric not null check(expected>=0), counted numeric not null check(counted>=0), reconciled boolean not null default false, unique(count_id,lot_id));
create table public.work_orders(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, number bigint generated always as identity unique, name text not null, description text, aircraft_id uuid references public.aircraft, mechanic_id uuid references public.mechanics, priority text not null default 'normal' check(priority in ('low','normal','high','critical')), status text not null default 'open' check(status in ('open','in_progress','waiting_part','waiting_tool','waiting_document','waiting_inspection','paused','administratively_complete','cancelled')), due_at timestamptz, closed_at timestamptz);
create table public.maintenance_tasks(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, description text, aircraft_id uuid references public.aircraft, work_order_id uuid references public.work_orders, mechanic_id uuid references public.mechanics, priority text not null default 'normal' check(priority in ('low','normal','high','critical')), status text not null default 'open' check(status in ('open','in_progress','waiting_part','waiting_tool','waiting_document','waiting_inspection','paused','administratively_complete','cancelled')), due_at timestamptz, closed_at timestamptz);
create table public.tools(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, code text not null unique, brand text, model text, serial_number text, owner_id uuid references public.organizations, location_id uuid not null references public.locations, status text not null default 'available' check(status in ('available','in_use','calibration','damaged','maintenance','quarantine','missing','retired')), calibration_required boolean not null default false, calibration_due date);
create table public.tool_kits(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, code text not null unique, require_check boolean not null default true);
create table public.tool_kit_items(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, kit_id uuid not null references public.tool_kits, tool_id uuid not null references public.tools, unique(kit_id,tool_id));
create table public.tool_checkouts(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, tool_id uuid not null references public.tools, mechanic_id uuid not null references public.mechanics, destination text not null, aircraft_id uuid references public.aircraft, task_id uuid references public.maintenance_tasks, work_order_id uuid references public.work_orders, due_at timestamptz, returned_at timestamptz, return_condition text, return_location_id uuid references public.locations);
create table public.tool_inspections(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, tool_id uuid references public.tools, kit_id uuid references public.tool_kits, name text not null, notes text, status text not null check(status in ('complete','discrepancy')), aircraft_id uuid references public.aircraft, check(tool_id is not null or kit_id is not null));
create table public.tool_discrepancies(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, tool_id uuid not null references public.tools, name text not null, aircraft_id uuid references public.aircraft, task_id uuid references public.maintenance_tasks, status text not null default 'open' check(status in ('open','investigating','resolved')), notes text);
create table public.tool_calibrations(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, tool_id uuid not null references public.tools, performed_at date not null, due_at date not null, result text not null check(result in ('accepted','rejected')), certificate_reference text not null, check(due_at>performed_at));
create table public.external_shipments(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, recipient_id uuid not null references public.organizations, purpose text not null, tracking_code text, carrier text, expected_return timestamptz, status text not null default 'preparing' check(status in ('preparing','dispatched','in_transit','received_by_third_party','waiting_service','returning','received_internally','pending_verification','administratively_closed')));
create table public.external_shipment_items(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, shipment_id uuid not null references public.external_shipments, lot_id uuid references public.stock_lots, part_instance_id uuid references public.part_instances, quantity numeric not null check(quantity>0), returned_quantity numeric not null default 0 check(returned_quantity>=0 and returned_quantity<=quantity), check((lot_id is null)<>(part_instance_id is null)), check(part_instance_id is null or quantity=1));
create table public.external_tracking_events(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, shipment_id uuid not null references public.external_shipments, name text not null, notes text);
create table public.documents(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, category text not null, reference_url text, notes text, expires_at date);
create table public.document_versions(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, document_id uuid not null references public.documents, revision int not null check(revision>0), object_path text not null unique, mime_type text not null, size_bytes bigint not null check(size_bytes>0 and size_bytes<=10485760), sha256 text not null, mechanic_id uuid not null references public.mechanics, unique(document_id,revision));
create table public.document_links(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, document_id uuid not null references public.documents, entity text not null, entity_id uuid not null);
create table public.alerts(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, severity text not null check(severity in ('info','warning','critical')), source_key text not null unique, entity text not null, entity_id uuid not null, status text not null default 'open' check(status in ('open','acknowledged','resolved')), notes text);
create table public.notification_rules(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, enabled boolean not null default true, days_before int not null default 15 check(days_before between 0 and 365), email_enabled boolean not null default false);
create table public.notification_recipients(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, email text not null unique, active boolean not null default true);
create table public.email_deliveries(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, alert_id uuid not null references public.alerts, recipient_id uuid not null references public.notification_recipients, dedup_key text not null unique, status text not null default 'pending' check(status in ('pending','sending','sent','failed')), attempts int not null default 0, next_attempt_at timestamptz not null default now(), lease_until timestamptz, provider_id text, last_error text);
create table public.import_jobs(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, name text not null, category text not null, total_rows int not null, success_rows int not null default 0, error_rows int not null default 0, status text not null default 'preview' check(status in ('preview','completed','partial')), mechanic_id uuid references public.mechanics);
create table public.import_job_rows(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, job_id uuid not null references public.import_jobs, row_number int not null, data jsonb not null, error text, unique(job_id,row_number));
create table public.activity_comments(id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version int not null default 1, archived_at timestamptz, entity text not null, entity_id uuid not null, body text not null, mechanic_id uuid not null references public.mechanics);

