create function public.take_attempt(p_key text,p_limit int) returns void language plpgsql security definer set search_path='' as $$
declare n int; begin
 insert into public.access_attempts as a(key,attempts,window_start) values(p_key,1,now()) on conflict(key) do update set attempts=case when a.window_start<now()-interval '15 minutes' then 1 else a.attempts+1 end,window_start=case when a.window_start<now()-interval '15 minutes' then now() else a.window_start end returning attempts into n;
 if n>p_limit then raise exception 'RATE_LIMIT';end if;
end $$;
-- On rejected requests the increment beyond the threshold rolls back; attempts remain at limit.
create function public.audit_change() returns trigger language plpgsql security definer set search_path='' as $$
declare actor uuid; op uuid; begin
 actor:=nullif(current_setting('app.mechanic_id',true),'')::uuid; op:=nullif(current_setting('app.operation_id',true),'')::uuid;
 if actor is null or op is null then raise exception 'FORBIDDEN';end if;
 insert into public.audit_events(entity,entity_id,action,before_data,after_data,mechanic_id,operation_id,reason) values(TG_TABLE_NAME,coalesce(NEW.id,OLD.id),TG_OP,case when TG_OP='INSERT' then null else to_jsonb(OLD) end,case when TG_OP='DELETE' then null else to_jsonb(NEW) end,actor,op,current_setting('app.reason',true));
 return coalesce(NEW,OLD);end $$;
create function public.touch_record() returns trigger language plpgsql set search_path='' as $$ begin NEW.updated_at=now();NEW.version=OLD.version+1;return NEW;end $$;
create function public.no_audit_rewrite() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'FORBIDDEN';end $$;
create trigger immutable_audit before update or delete on public.audit_events for each row execute function public.no_audit_rewrite();
create function public.guard_location_cycle() returns trigger language plpgsql set search_path='' as $$ begin
 perform pg_advisory_xact_lock(914113);
 if exists(with recursive ancestors as (select id,parent_id from public.locations where id=NEW.parent_id union select l.id,l.parent_id from public.locations l join ancestors a on l.id=a.parent_id) select 1 from ancestors where id=NEW.id) then raise exception 'INVALID_OPERATION'; end if;return NEW;end $$;
create trigger locations_no_cycle before insert or update on public.locations for each row execute function public.guard_location_cycle();
